it('wraps a rejection that is not an Error so onError still fires, while an Error passes through unchanged', async () => {
  const callOrder: string[] = [];
  let received: Error | undefined;
  const hooks: OrchestratorHooks = {
    onError: async (_session, error) => {
      callOrder.push('onError');
      received = error;
    },
    afterSession: async () => void callOrder.push('afterSession'),
  };

  const rejectingWith = (reason: unknown): AIProvider => ({
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw reason;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  });

  const turn = async (reason: unknown) => {
    received = undefined;
    callOrder.length = 0;
    const outcome = await createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {hooks})
      .processMessage(createSession('hello'))
      .then(
        () => ({rejected: false, value: undefined as unknown}),
        (thrown: unknown) => ({rejected: true, value: thrown})
      );

    return {
      outcome,
      callOrder: [...callOrder],
      isError: received instanceof Error,
      message: received?.message,
      cause: received?.cause,
      hookGotOriginal: received === reason,
      callerGotOriginal: outcome.value === reason,
    };
  };

